import { SEO_API_URL, SITE_URL } from "@/lib/seo";

export const revalidate = 300;

/**
 * Canonical sitemap index at /sitemap.xml (the URL already in robots.txt and GSC).
 * Child sitemaps are generated by `app/sitemaps/sitemap.ts` via generateSitemaps().
 */
export async function GET() {
  let productPages = 1;
  try {
    const res = await fetch(`${SEO_API_URL}/seo/sitemap?part=meta`, {
      next: { revalidate: 300 },
    });
    if (res.ok) {
      const data = (await res.json()) as { productPages?: number };
      productPages = Math.max(1, Number(data.productPages) || 1);
    }
  } catch {
    productPages = 1;
  }

  const locs = [
    `${SITE_URL}/sitemaps/sitemap/0.xml`,
    ...Array.from(
      { length: productPages },
      (_, i) => `${SITE_URL}/sitemaps/sitemap/${i + 1}.xml`,
    ),
  ];

  const body = `<?xml version="1.0" encoding="UTF-8"?>
<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${locs.map((loc) => `  <sitemap><loc>${loc}</loc></sitemap>`).join("\n")}
</sitemapindex>
`;

  return new Response(body, {
    headers: {
      "Content-Type": "application/xml; charset=utf-8",
      "Cache-Control":
        "public, max-age=60, s-maxage=300, stale-while-revalidate=86400",
    },
  });
}
